use super::*;
use std::io::Cursor;
const FONT:&[u8]=include_bytes!("../../../../../03_infra/fixtures/fonts/NotoSans-Regular.ttf");
fn compare(data:&[u8],index:u32,coverage:bool){let expected=info(data,index,coverage);let actual=selective::read(&mut Cursor::new(data),data.len() as u64,index,coverage).and_then(|(b,_)|info(&b,0,coverage));assert_eq!(actual,expected);}
fn replace_table(mut data:Vec<u8>,tag:&[u8;4],body:&[u8])->Vec<u8>{let n=u16::from_be_bytes(data[4..6].try_into().unwrap()) as usize;let at=(0..n).map(|i|12+i*16).find(|&i|&data[i..i+4]==tag).unwrap();let offset=data.len() as u32;data[at+8..at+12].copy_from_slice(&offset.to_be_bytes());data[at+12..at+16].copy_from_slice(&(body.len() as u32).to_be_bytes());data.extend_from_slice(body);data}
#[test]fn fixtures_preserve_metadata_and_coverage(){for p in std::fs::read_dir(concat!(env!("CARGO_MANIFEST_DIR"), "/../../../../03_infra/fixtures/fonts")).unwrap(){let p=p.unwrap().path();if matches!(p.extension().and_then(|x|x.to_str()),Some("ttf"|"otf")){let data=std::fs::read(p).unwrap();compare(&data,0,false);compare(&data,0,true);}}}
#[test]fn collection_offsets_and_face_indices(){let mut out=b"ttcf\0\x01\0\0\0\0\0\x02\0\0\0\x14\0\0\0\x14".to_vec();let mut face=FONT.to_vec();let n=u16::from_be_bytes(face[4..6].try_into().unwrap()) as usize;for i in 0..n{let at=12+i*16+8;let o=u32::from_be_bytes(face[at..at+4].try_into().unwrap())+20;face[at..at+4].copy_from_slice(&o.to_be_bytes());}out.extend_from_slice(&face);for index in 0..=2{compare(&out,index,true);}compare(FONT,1,true);}
#[test]fn post_prefix_retains_validation_and_fixed_pitch(){for version in [0u32,0x10000,0x20000,0x25000,0x30000,0x40000]{for len in [0,4,16,31,32,33,34,35,38,1000]{let mut p=vec![0;len];if len>=4{p[..4].copy_from_slice(&version.to_be_bytes());}if len>=16{p[12..16].copy_from_slice(&1u32.to_be_bytes());}if len>=34{p[32..34].copy_from_slice(&2u16.to_be_bytes());}let d=replace_table(FONT.to_vec(),b"post",&p);compare(&d,0,false);}}}
#[test]fn optional_and_mandatory_table_bounds(){for tag in [b"post",b"head",b"name",b"OS/2"]{let mut d=FONT.to_vec();let n=u16::from_be_bytes(d[4..6].try_into().unwrap()) as usize;let at=(0..n).map(|i|12+i*16).find(|&i|&d[i..i+4]==tag).unwrap();d[at+8..at+12].copy_from_slice(&u32::MAX.to_be_bytes());compare(&d,0,false);}}
#[test]fn malformed_headers_reject_without_panic(){for len in [0,1,4,8,11,12,20,40]{compare(&FONT[..len],0,true);}let mut b=FONT.to_vec();b[..4].copy_from_slice(b"xxxx");compare(&b,0,true);let b=b"ttcf\0\x01\0\0\xff\xff\xff\xff";assert!(selective::read(&mut Cursor::new(b),b.len() as u64,0,true).is_none());}
#[test]fn omitted_payload_and_prefix_reduce_reads(){let mut p=vec![0;1_000_000];p[..4].copy_from_slice(&0x30000u32.to_be_bytes());let d=replace_table(FONT.to_vec(),b"post",&p);let(b,read)=selective::read(&mut Cursor::new(&d),d.len() as u64,0,false).unwrap();assert!(read<d.len() as u64/10);assert_eq!(info(&b,0,false),info(&d,0,false));}
